// ---------- option order ----------
const ROMAN = ['I', 'II', 'III', 'IV', 'V'];
function numericValue(text: string): number | null {
  const t = text.replace(/−/g, '-').replace(/\./g, ':').replace(/,/g, '.').trim();
  if (ROMAN.includes(text)) return ROMAN.indexOf(text) + 1;
  if (/^-?\d+(\.\d+)?$/.test(t)) return Number(t);
  if (/^-?\d+\/\d+$/.test(t)) {
    const [a, b] = t.split('/').map(Number);
    return a / b;
  }
  if (/^\d{2}:\d{2}$/.test(t)) {
    const [h, m] = t.split(':').map(Number);
    return h * 60 + m;
  }
  return null;
}

function placeOptions(seed: Seed, index: number) {
  const correct = seed.options[0];
  const values = seed.options.map(numericValue);
  let options: string[];
  if (values.every((v) => v !== null)) {
    // like ÖSYM: number answers from smallest to largest (and I–V in order)
    options = seed.options.map((text, i) => ({ text, v: values[i] as number })).sort((a, b) => a.v - b.v).map((o) => o.text);
  } else {
    const position = (index * 3 + Math.floor(index / 5)) % 5;
    const rest = seed.options.slice(1);
    rest.splice(position, 0, correct);
    options = rest;
  }
  return { options, answer: TYT_LETTERS[options.indexOf(correct)] };
}

const counters: Record<string, number> = {};
export const TYT_QUESTIONS: TytQuestion[] = SEEDS.map((seed, index) => {
  counters[seed.subject] = (counters[seed.subject] ?? 0) + 1;
  const { options, answer } = placeOptions(seed, index);
  return { ...seed, id: `tyt-${seed.subject}-${counters[seed.subject]}`, options, answer };
});

export const TYT_BY_ID = new Map(TYT_QUESTIONS.map((question) => [question.id, question]));
